// 三条直接 => 拐弯不超过两次 
bool check(vector<vector<string>>& grid, int x1 , int y1, int x2, int y2) {
    if (grid[x1][y1] != grid[x2][y2]) {
        return false;
    }

    // 同一个点不能连接
    if (x1 == x2 && y1 == y2) {
​
        return false;
    } 
​
    int n = grid.size();
    int m = grid[0].size();

    // 表示到达该处的最小拐弯数
    int visited[n *m][4]; 
    memset(visited, 0x3f, sizeof(visited)); // 初始化为大数
    queue<State> q;
​
    // 起点四个方向均可，拐弯数0
    for (int dir = 0; dir < 4; dir++) {
        visited[x1 * m + y1][dir] = 0;
        q.push({x1, y1, dir, 0});
    }
​
    while (!q.empty()) {
        auto [x, y, dir, usedT] = q.front();
        q.pop();
        if (x == x2 && y == y2) {
            // 地图消除
            grid[x1][y1] = "*";
            grid[x2][y2] = "*";
            return true;
        }

        for (int ndir = 0; ndir < 4; ndir++) {
            int nx = x + dx[ndir];
            int ny = y + dy[ndir];
            // 超出边界
            if (nx < 0 || ny < 0 || nx >= n || ny >= m) {
                continue;
            }
            // 不是空白区域 也不是目的地
            if (!(nx == x2 && ny == y2) && grid[nx][ny] != "*") {
                continue;
            }
            int nUsedT = usedT;
            // 更新拐弯数
            if (ndir != dir) {
                nUsedT++;
            }
            if (nUsedT > 2) {
                continue;
            }

            int pos = nx * m + ny;
            // 剪枝
            if (nUsedT >= visited[pos][ndir]){
                continue;
            }

            visited[pos][ndir] = nUsedT;
            q.push({nx, ny, ndir, nUsedT});
        }
    }
​
    return false;
}
