function check(grid, x1, y1, x2, y2) {
    // 起点和终点不是同一值
    if (grid[x1][y1] !== grid[x2][y2]) return false;
    // 起点和终点不能是同一位置
    if (x1 === x2 && y1 === y2) return false;
