    const queue = [];
    // 起点不限方向
    for (let dir = 0; dir < 4; dir++) {
        visited[x1 * m + y1][dir] = 0;
        queue.push({ x: x1, y: y1, dir, usedT: 0 });
    }

    while (queue.length > 0) {
        const { x, y, dir, usedT } = queue.shift();
        if (x === x2 && y === y2) {
            grid[x1][y1] = "*";
            grid[x2][y2] = "*";
            return true;
        }
        for (let ndir = 0; ndir < 4; ndir++) {
            const nx = x + dx[ndir];
            const ny = y + dy[ndir];
            // 超出边界
            if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
            // 不是目标地也不是空白区域
            if (!(nx === x2 && ny === y2) && grid[nx][ny] !== "*") continue;
            // 更新拐弯数
            let nUsedT = usedT + (ndir !== dir ? 1 : 0);
            if (nUsedT > 2) continue;
            const pos = nx * m + ny;
            // 剪枝
            if (nUsedT >= visited[pos][ndir]) continue;
            visited[pos][ndir] = nUsedT;
            queue.push({ x: nx, y: ny, dir: ndir, usedT: nUsedT });
        }
    }
    return false;
}
