package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 方向数组：上0，下1，左2，右3
var dx = []int{-1, 1, 0, 0}
var dy = []int{0, 0, -1, 1}
​
// 状态结构体，表示当前坐标、方向、已使用的拐弯数
type State struct {
    x, y, dir, turn int
}
​
// 判断两个点是否可以连接（使用不超过两次转弯）
func check(grid [][]string, x1, y1, x2, y2 int) bool {
    if grid[x1][y1] != grid[x2][y2] {
        return false // 内容不一致
    }
    if x1 == x2 && y1 == y2 {
        return false // 起点终点相同
    }
​
    n, m := len(grid), len(grid[0])
    // visited[pos][dir] 表示从某个方向走到该点最少用了多少次转弯
    visited := make([][]int, n*m)
    for i := range visited {
        visited[i] = make([]int, 4)
        for j := range visited[i] {
            visited[i][j] = 1 << 30 // 初始化为正无穷
        }
    }
​
    queue := []State{}
    // 初始四个方向都尝试作为起点
    for dir := 0; dir < 4; dir++ {
        visited[x1*m+y1][dir] = 0
        queue = append(queue, State{x1, y1, dir, 0})
    }
​
    for len(queue) > 0 {
        cur := queue[0]
        queue = queue[1:]
​
        // 到达目标点
        if cur.x == x2 && cur.y == y2 {
            grid[x1][y1] = "*"
            grid[x2][y2] = "*"
            return true
        }
​
        for ndir := 0; ndir < 4; ndir++ {
            nx := cur.x + dx[ndir]
            ny := cur.y + dy[ndir]
            if nx < 0 || ny < 0 || nx >= n || ny >= m {
                continue
            }
            // 只能走空格（*）或者目标点
            if !(nx == x2 && ny == y2) && grid[nx][ny] != "*" {
                continue
            }
​
            turns := cur.turn
            if ndir != cur.dir {
                turns++
            }
            if turns > 2 {
                continue
            }
​
            pos := nx*m + ny
            if turns >= visited[pos][ndir] {
                continue
            }
            visited[pos][ndir] = turns
            queue = append(queue, State{nx, ny, ndir, turns})
        }
    }
    return false
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    inputLine := scanner.Text()
​
    // 去除开头结尾的 [[ 和 ]]
    inputLine = strings.TrimPrefix(inputLine, "[[")
    inputLine = strings.TrimSuffix(inputLine, "]]")
    rows := strings.Split(inputLine, "],[")
​
    // 构造地图
    tmpGrid := [][]string{}
    for _, row := range rows {
        tmpGrid = append(tmpGrid, strings.Split(row, ","))
    }
    n, m := len(tmpGrid), len(tmpGrid[0])
    grid := [][]string{}
​
    // 上边界
    grid = append(grid, make([]string, m+2))
    for i := range grid[0] {
        grid[0][i] = "*"
    }
​
    // 中间数据 + 左右边界
    for i := 0; i < n; i++ {
        newRow := []string{"*"}
        newRow = append(newRow, tmpGrid[i]...)
        newRow = append(newRow, "*")
        grid = append(grid, newRow)
    }
​
    // 下边界
    bottom := make([]string, m+2)
    for i := range bottom {
        bottom[i] = "*"
    }
    grid = append(grid, bottom)
​
    // 读取操作次数
    scanner.Scan()
    count, _ := strconv.Atoi(scanner.Text())
​
    for i := 0; i < count; i++ {
        scanner.Scan()
        parts := strings.Fields(scanner.Text())
        y1, _ := strconv.Atoi(parts[0])
        x1, _ := strconv.Atoi(parts[1])
        y2, _ := strconv.Atoi(parts[2])
        x2, _ := strconv.Atoi(parts[3])
​
        // +1 是因为我们添加了边界
        if !check(grid, x1+1, y1+1, x2+1, y2+1) {
            fmt.Println("NO")
            return
        }
    }
    fmt.Println("OK")
}
